// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, 750, 600);

var C = {
  shell: '#4d4d4d', melt: '#c9cbe8', meltTop: '#dee1f2', surf: '#7f9fd6',
  orange: '#e59b6f', orangeDk: '#b97346', cath: '#2f2f4a',
  green: '#d9e4b2', greenPale: '#eef3e0', bub: '#dee7a4', bubEdge: '#93a755',
  pink: '#f0cfe1', pinkPale: '#fbf3f7', pinkLn: '#e08cb8',
  flange: '#b9c4e0', gray: '#9c9c9c', na: '#3566cc', cl: '#3d9b4f'
};

var S = draw.group();
var gGlow = draw.group();
var gIons = draw.group();
var gLab = draw.group();
var gCard = draw.group();
var gPaths = draw.group().opacity(0);

/* ---------- helpers ---------- */
function txt(p, x, y, s, size, anchor, color, halo) {
  var t = p.text('');
  t.plain(s);
  t.font({ family: 'Helvetica, Arial, sans-serif', size: size || 14, anchor: anchor || 'start' });
