/* ---------- particle system ---------- */
var running = false, screenOn = true, parts = [], flows = [];

function clearParticles() { gIons.clear(); parts = []; flows = []; }

function spawnIon(type) {
  var x, y, tx, ty, el;
  y = 300 + Math.random() * 155;
  if (type === 'cl') {
    var side = Math.random() < 0.5 ? -1 : 1;
    x = 323 + side * (70 + Math.random() * 130);
    x = Math.max(188, Math.min(460, x));
    tx = x < 323 ? 308 : 338;
    ty = 368 + Math.random() * 24;
    el = gIons.circle(9.5).center(x, y).fill(C.cl).stroke({ color: '#245c2c', width: 0.8 });
  } else {
    x = 245 + Math.random() * 156;
    tx = x < 323 ? 226 : 420;
    ty = 366 + Math.random() * 26;
    el = gIons.circle(9.5).center(x, y).fill(C.na).stroke({ color: '#1b3d80', width: 0.8 });
  }
  parts.push({ el: el, type: type, x: x, y: y, tx: tx, ty: ty, sp: 24 + Math.random() * 18 });
}

function addFlow(kind, path, stray) {
  var el;
  if (kind === 'bub') el = gIons.ellipse(11, 9).center(0, 0).fill(C.bub).stroke({ color: C.bubEdge, width: 1 });
  else el = gIons.circle(9.5).center(0, 0).fill('#eaa6cd').stroke({ color: '#bd6b93', width: 1 });
  flows.push({ el: el, p: path, d: 0, sp: kind === 'bub' ? 78 : 50, kind: kind, stray: !!stray });
}

function starPts(x, y, R, r, n) {
  var pts = [];
  for (var i = 0; i < n * 2; i++) {
    var rad = (i % 2 === 0) ? R : r, a = (Math.PI * i) / n - Math.PI / 2;
    pts.push([x + Math.cos(a) * rad, y + Math.sin(a) * rad]);
  }
  return pts;
}
function flashAt(x, y) {
  var g = gIons.group();
  g.circle(30).center(x, y).fill('#ff8a2a').opacity(0.55);
  g.polygon(starPts(x, y, 19, 8, 8)).fill('#ffd24d').opacity(0.95);
  g.animate(650).opacity(0);
  setTimeout(function () { try { g.remove(); } catch (e) { } }, 700);
}

function stepSim(dt) {
  var wantCl = 10, wantNa = 10, nCl = 0, nNa = 0, i;
  for (i = 0; i < parts.length; i++) { if (parts[i].type === 'cl') nCl++; else nNa++; }
  if (nCl < wantCl) spawnIon('cl');
  if (nNa < wantNa) spawnIon('na');

  for (i = parts.length - 1; i >= 0; i--) {
    var p = parts[i];
    var dx = p.tx - p.x, dy = p.ty - p.y, d = Math.sqrt(dx * dx + dy * dy);
    if (d < 6) {
      p.el.remove(); parts.splice(i, 1);
      if (p.type === 'cl') {
        if (!screenOn && Math.random() < 0.7) addFlow('bub', Math.random() < 0.5 ? P.sbL : P.sbR, true);
        else addFlow('bub', P.duct, false);
      } else {
        var left = p.tx < 323;
        if (!screenOn && Math.random() < 0.7) addFlow('drop', left ? P.sdL : P.sdR, true);
        else addFlow('drop', left ? P.naL : P.naR, false);
      }
      continue;
    }
    p.x += (dx / d) * p.sp * dt;
    p.y += (dy / d) * p.sp * dt;
    p.el.center(p.x, p.y);
  }

  for (i = flows.length - 1; i >= 0; i--) {
    var f = flows[i];
    f.d += f.sp * dt;
    if (f.d >= f.p.len) { f.el.remove(); flows.splice(i, 1); continue; }
    var pt = f.p.node.getPointAtLength(f.d);
    f.px = pt.x; f.py = pt.y;
    f.el.center(pt.x, pt.y);
    f.el.opacity(Math.min(1, (f.p.len - f.d) / 22));
  }

  if (!screenOn) {
    for (i = flows.length - 1; i >= 0; i--) {
      var b = flows[i];
      if (!b || b.kind !== 'bub' || !b.stray) continue;
      for (var j = flows.length - 1; j >= 0; j--) {
        var s = flows[j];
        if (!s || s.kind !== 'drop' || !s.stray) continue;
        var ddx = b.px - s.px, ddy = b.py - s.py;
        if (ddx * ddx + ddy * ddy < 400) {
          flashAt((b.px + s.px) / 2, (b.py + s.py) / 2);
          b.el.remove(); s.el.remove();
          flows.splice(Math.max(i, j), 1);
          flows.splice(Math.min(i, j), 1);
          break;
        }
      }
    }
  }
}

/* ---------- animation loop ---------- */
var activeGlow = null, last = 0;
function frame(ts) {
  var dt = last ? Math.min(0.05, (ts - last) / 1000) : 0;
  last = ts;
  if (running) stepSim(dt);
  var pulse = 0.22 + 0.2 * (0.5 + 0.5 * Math.sin(ts / 260));
  anodeGlow.opacity(activeGlow === 'anode' ? pulse : 0);
  cathGlow.opacity(activeGlow === 'cathode' ? pulse : 0);
  screenGlow.opacity(activeGlow === 'screen' ? pulse : 0);
  requestAnimationFrame(frame);
}
requestAnimationFrame(frame);

